async function urunkCrmRoute(request,env,url){
 const fail=(msg,status)=>urunkCrmResponse(msg,status,"text/plain; charset=utf-8",request.method);
 if(url.hostname!=="urunk.com")return fail("Not found",404);
 if(!["GET","HEAD","POST"].includes(request.method))return fail("Method not allowed",405);
 if(!await urunkGrowthAuthorized(request,env))return fail("Authentication required",403);
 if(!env.CRM_DB)return fail("CRM unavailable",503);
 const path=url.pathname.replace(/\/$/,""),db=env.CRM_DB,month=urunkCrmMonth(url.searchParams.get("month"));
 if(!["/private/growth/crm","/private/growth/crm/export"].includes(path))return fail("Not found",404);
 try{
  if(request.method==="POST"){
   if(path!=="/private/growth/crm")return fail("Method not allowed",405);
   if(request.headers.get("Origin")!=="https://urunk.com"||request.headers.get("Sec-Fetch-Site")==="cross-site")return fail("Forbidden origin",403);
   if(!(request.headers.get("Content-Type")||"").startsWith("application/x-www-form-urlencoded"))return fail("Unsupported content type",415);
   const b=await readBoundedBody(request,8192);if(!b.ok)return fail("Payload too large",413);
   const f=new URLSearchParams(b.text),csrf=await urunkCrmCsrf(request);
   if(f.get("csrf")!==csrf)return fail("Invalid CSRF",403);
   const id=f.get("id")||"",revision=f.has("revision")?Number(f.get("revision")):-1;
   if(!/^[0-9a-f-]{36}$/i.test(id)||!Number.isSafeInteger(revision)||revision<0)return fail("Invalid request",400);
   const action=f.get("action"),now=new Date().toISOString();
   if(action==="update"){
    const stage=f.get("stage")||"",raw=f.get("value")||"",value=Math.round(Number(raw)*100),date=f.get("follow_up")||"",note=(f.get("note")||"").trim();
    if(!URUNK_CRM_STAGES.includes(stage)||!/^\d{1,10}(\.\d{1,2})?$/.test(raw)||!Number.isSafeInteger(value)||value<0||value>100000000000||note.length>2000||(date&&(!/^\d{4}-\d{2}-\d{2}$/.test(date)||!Number.isFinite(Date.parse(date))||new Date(date).toISOString().slice(0,10)!==date)))return fail("Invalid fields",400);
    const r=await db.prepare("UPDATE crm_leads SET stage=?,value_minor=?,follow_up=?,note=?,updated_at=?,revision=revision+1 WHERE id=? AND revision=? RETURNING id").bind(stage,value,date,note,now,id,revision).first();if(!r?.id)return fail("Conflict; reload the record",409);
   }else if(action==="delivery"){
    const lead=await db.prepare("SELECT provider_id,notification_status FROM crm_leads WHERE id=?").bind(id).first();
    if(!lead||!lead.provider_id||!/^[A-Za-z0-9_-]{8,128}$/.test(lead.provider_id)||!env.RESEND_API_KEY)return fail("Delivery status unavailable",409);
    let res;try{res=await fetch("https://api.resend.com/emails/"+encodeURIComponent(lead.provider_id),{headers:{Authorization:"Bearer "+env.RESEND_API_KEY},redirect:"error",signal:AbortSignal.timeout(5000)})}catch{return fail("Provider unavailable",502)}
    if(!res.ok)return fail("Provider status not accessible",502);
    const data=await res.json(),status=String(data.last_event||"");
    if(!["sent","delivered","bounced","complained","delivery_delayed","suppressed","failed"].includes(status))return fail("No verified delivery state available",409);
    const r=await db.prepare("UPDATE crm_leads SET notification_status=?,notification_updated_at=? WHERE id=? AND notification_status=? RETURNING id").bind(status,now,id,lead.notification_status).first();if(!r?.id)return fail("Status changed; retry",409);
   }else if(action==="erase"){
    if(f.get("confirm")!=="SUPPRIMER")return fail("Confirmation required",400);
    const r=await db.batch([db.prepare("DELETE FROM crm_history WHERE lead_id=? AND EXISTS(SELECT 1 FROM crm_leads WHERE id=? AND revision=?)").bind(id,id,revision),db.prepare("DELETE FROM crm_leads WHERE id=? AND revision=?").bind(id,revision)]);if(!r.every(x=>x.success)||r[1].meta?.changes!==1)return fail("Conflict; reload the record",409);
   }else return fail("Invalid action",400);
   const out=urunkCrmResponse(null,303,"text/plain; charset=utf-8");out.headers.set("Location","/private/growth/crm");return out;
  }
  if(path.endsWith("/export")){
   const r=await db.prepare("SELECT stage,source,COUNT(*) AS leads,COALESCE(SUM(value_minor),0) AS value_minor FROM crm_leads WHERE substr(created_at,1,7)=? GROUP BY stage,source ORDER BY stage,source").bind(month).all();
   if(!r.success)return fail("Report unavailable",503);
   const lines=[["month","stage","form_source","leads","declared_value_MAD"],...r.results.map(x=>[month,x.stage,x.source,x.leads,(x.value_minor/100).toFixed(2)])].map(x=>x.map(urunkCrmCsvCell).join(",")).join("\r\n");
   const out=urunkCrmResponse(lines,200,"text/csv; charset=utf-8",request.method);out.headers.set("Content-Disposition",'attachment; filename="urunk-crm-'+month+'.csv"');return out;
  }
  const filter=URUNK_CRM_STAGES.includes(url.searchParams.get("stage"))?url.searchParams.get("stage"):"all",rawPage=Number(url.searchParams.get("page")||0),page=Number.isSafeInteger(rawPage)?Math.max(0,Math.min(1000,rawPage)):0;
  const [r,s]=await Promise.all([db.prepare("SELECT * FROM crm_leads WHERE substr(created_at,1,7)=? AND (?='all' OR stage=?) ORDER BY created_at DESC,id DESC LIMIT 25 OFFSET ?").bind(month,filter,filter,page*25).all(),db.prepare("SELECT stage,COUNT(*) AS n,COALESCE(SUM(value_minor),0) AS value FROM crm_leads WHERE substr(created_at,1,7)=? GROUP BY stage").bind(month).all()]);
  if(!r.success||!s.success)return fail("CRM unavailable",503);
  return urunkCrmResponse(urunkCrmRender(r.results,s.results,await urunkCrmCsrf(request),filter,page,month),200,"text/html; charset=utf-8",request.method);
 }catch{console.error(JSON.stringify({code:"CRM_ROUTE_FAILED"}));return fail("CRM unavailable",503)}
}

const urunkOriginalFetch = worker_default.fetch.bind(worker_default);
worker_default.fetch = async function(request,env,ctx) {
  const url=new URL(request.url);
  if(url.pathname==="/private/growth/crm"||url.pathname.startsWith("/private/growth/crm/"))return urunkCrmRoute(request,env,url);
  if(url.pathname==="/private/growth"||url.pathname.startsWith("/private/growth/"))return urunkGrowthRoute(request,env,url);
  if(url.hostname==="www.urunk.com" || url.pathname.startsWith("/api/")) return urunkOriginalFetch(request,env,ctx);
  if(request.method==="GET"||request.method==="HEAD"){
    if(url.pathname==="/robots.txt")return urunkTextResource(request,URUNK_ROBOTS_V34);
    if(url.pathname==="/llms.txt")return urunkTextResource(request,URUNK_LLMS_V34);
  }
  if(request.method!=="GET"&&request.method!=="HEAD")return urunkOriginalFetch(request,env,ctx);
  if(url.pathname.startsWith("/assets/urunk-fonts-v45/"))return urunkFont45(request,url);
  const activePrefix=url.pathname.startsWith(URUNK_PATCH_PREFIX)?URUNK_PATCH_PREFIX:URUNK_LEGACY_PREFIXES.find(p=>url.pathname.startsWith(p))||null;
  const isVirtual=!!activePrefix;
  if(isVirtual&&url.pathname===activePrefix+"authority-content.json"){
    const path=url.searchParams.get("path")||"";
    const html=Object.hasOwn(URUNK_AUTHORITY_BLOCKS,path)?URUNK_AUTHORITY_BLOCKS[path]:null;
    return new Response(request.method==="HEAD"?null:JSON.stringify(html?{path,html}:{error:"Not found"}),{status:html?200:404,headers:{"content-type":"application/json; charset=utf-8","cache-control":"public, max-age=3600","x-content-type-options":"nosniff","x-urunk-content-release":"v45-live-overlay"}});
  }
  if(request.method==="HEAD"&&!isVirtual)return urunkOriginalFetch(request,env,ctx);
  const originalPath=isVirtual ? "/assets/"+url.pathname.slice(activePrefix.length) : url.pathname;
  if(isVirtual && !/^\/assets\/[A-Za-z0-9_.-]+$/.test(originalPath))return new Response("Not found",{status:404});
  const headers=new Headers(request.headers);
  if(isVirtual || !originalPath.startsWith("/assets/")){
    headers.delete("if-none-match");headers.delete("if-modified-since");headers.delete("range");
  }
  const target=new URL(url);target.pathname=URUNK_BLOG_ARTICLE_ALIASES.has(originalPath)?"/assets/chunk-post-c7uz01dz.js":originalPath;
  const response=await urunkOriginalFetch(new Request(target.toString(),{method:"GET",headers}),env,ctx);
  if(response.status!==200)return request.method==="HEAD"?new Response(null,{status:response.status,headers:response.headers}):response;
  if(/^\/_seo\/[a-z0-9/-]+\.json$/.test(url.pathname)){
    try{
      const json=await response.clone().json();
      const page=url.pathname.slice(5,-5)==="/index"?"/":url.pathname.slice(5,-5);
      if(typeof json.markup==="string"){
        const patched=urunkPatchText(json.markup,false);
        const normalized=urunkNormalizeSchema(patched.text,page);
        const authority=urunkAuthorityApply(normalized.text,page,true);
        json.markup=authority.text;
        const h=new Headers(response.headers);
        for(const k of ["content-length","content-encoding","etag","last-modified","content-md5","accept-ranges"])h.delete(k);
        h.set("cache-control","public, max-age=0, must-revalidate");
        h.set("cdn-cache-control","no-store");h.set("cloudflare-cdn-cache-control","no-store");
        h.set("x-urunk-content-release","v45-live-overlay");
        return new Response(JSON.stringify(json),{status:200,headers:h});
      }
    }catch{}
    return response;
  }
  const ct=response.headers.get("content-type")||"";
  const html=ct.includes("text/html")&&!isVirtual;
  const javascript=isVirtual&&/\.(?:js|mjs)$/.test(originalPath)&&/javascript|ecmascript/.test(ct);
  if(!html&&!javascript){
    if(isVirtual&&/\.css$/.test(originalPath)&&ct.includes("text/css")){
      if(originalPath==="/assets/index-dzwlw4ue.css")return urunkAssetResponse(response,(await response.text())+"\n"+URUNK_FONT_CSS_45+"\n"+URUNK_DESIGN_V43+"\n"+URUNK_UX_V44,request,originalPath,activePrefix,true,1);
      return urunkAssetResponse(response,response.body,request,originalPath,activePrefix,false,0);
    }
    return request.method==="HEAD"?new Response(null,{status:response.status,headers:response.headers}):response;
  }
  const original=await response.text();
  let result=html || URUNK_PATCH_DATA.has(originalPath) ? urunkPatchText(original,javascript) : {text:original,count:0};
  if(html){const normalized=urunkNormalizeSchema(result.text,url.pathname);result.text=normalized.text;result.count+=normalized.count;}
  if(javascript){result.text=result.text.replace(/(["'])@type\1\s*:\s*(["'])ProfessionalService\2/g,'$1@type$1:$2LocalBusiness$2').replace(/(["'])@type\1\s*:\s*\[\s*(["'])ProfessionalService\2\s*,\s*(["'])DigitalMarketingAgency\3\s*\]/g,'$1@type$1:"LocalBusiness"').replace(/(["'])@type\1\s*:\s*\[\s*(["'])LocalBusiness\2\s*,\s*(["'])ProfessionalService\3\s*\]/g,'$1@type$1:"LocalBusiness"');}
  if(html||javascript){const optimized=urunkHomeOptimize(result.text,html?url.pathname:originalPath,html);result.text=optimized.text;result.count+=optimized.count;}
  if(html||javascript){const optimized=urunkBlogOptimize(result.text,html?url.pathname:originalPath,html);result.text=optimized.text;result.count+=optimized.count;}
  if(html||javascript){const editorial=urunkEditorialV36(result.text,html?url.pathname:originalPath,html);result.text=editorial.text;result.count+=editorial.count;}
  if(html||javascript){const authority=urunkAuthorityApply(result.text,html?url.pathname:originalPath,html);result.text=authority.text;result.count+=authority.count;}
  if(html||javascript){const ux=urunkUX44(result.text,html?url.pathname:originalPath,html);result.text=ux.text;result.count+=ux.count;}
  if(html||javascript){const perf=urunkPerformance45(result.text,html?url.pathname:originalPath,html);result.text=perf.text;result.count+=perf.count;}
  result.text=urunkPatchAssetLinks(result.text,javascript);
  if(javascript){
    return urunkAssetResponse(response,result.text,request,originalPath,activePrefix,true,result.count);
  }
  if(result.text===original)return new Response(original,{status:response.status,headers:response.headers});
  const h=new Headers(response.headers);for(const k of ["content-length","content-encoding","etag","last-modified","content-md5","accept-ranges"])h.delete(k);
  h.set("x-urunk-content-release","v45-live-overlay");
  h.set("x-urunk-content-edits",String(result.count));
  h.set("cache-control",html?"public, max-age=0, must-revalidate":"public, max-age=3600");
  h.set("cdn-cache-control","no-store");h.set("cloudflare-cdn-cache-control","no-store");
  return new Response(result.text,{status:200,headers:h});
};
